const pickCI=(obj,key)=>{
 if(!obj||typeof obj!=='object') return '';
 const hit=Object.keys(obj).find(k=>k.toLowerCase()===String(key).toLowerCase());
 return hit ? (obj[hit] ?? '') : '';
};
const header=(src,key)=>{
 const k=String(key).toLowerCase();
 if (Array.isArray(src)) return (src.find(h=>String(h?.name||'').toLowerCase()===k)?.value)||'';
 if (src && typeof src==='object') {
   const hit=Object.keys(src).find(x=>x.toLowerCase()===k);
   return hit ? (src[hit]||'') : '';
 }
 return '';
};
const getEmailAddress=(value)=>{
 if(!value) return '';
 if(typeof value==='string') return (value.match(/<([^>]+)>/)?.[1]||value).trim();
 if(Array.isArray(value)) return getEmailAddress(value[0]);
 if(typeof value==='object') {
   if(Array.isArray(value.value)) return getEmailAddress(value.value[0]);
   if(typeof value.address==='string') return value.address.trim();
   if(typeof value.text==='string') return getEmailAddress(value.text);
 }
 return '';
};
const decode=(data)=>{
 if(typeof data!=='string'||!data) return '';
 try{return Buffer.from(data.replace(/-/g,'+').replace(/_/g,'/'),'base64').toString('utf8');}catch{return '';}
};
const bodyFrom=(part,mime)=>{
 if(!part||typeof part!=='object') return '';
 if(String(part.mimeType||'').toLowerCase()===mime) return decode(part.body?.data);
 for(const child of (part.parts||[])){const result=bodyFrom(child,mime);if(result) return result;}
 return '';
};
const htmlToText=(html)=>String(html||'').replace(/<style[\s\S]*?<\/style>/gi,'').replace(/<script[\s\S]*?<\/script>/gi,'').replace(/<br\s*\/?>/gi,'\n').replace(/<\/p>/gi,'\n\n').replace(/<[^>]+>/g,'').replace(/&nbsp;/gi,' ').replace(/&amp;/gi,'&').trim();
return items.map(i=>{
 const p=i.json.payload||{};
 const hdrs=i.json.headers||p.headers||[];
 const fromValue=i.json.from||pickCI(i.json,'from')||header(hdrs,'from')||'';
 const fromEmail=getEmailAddress(fromValue);
 const fromRaw=typeof fromValue==='object'?(fromValue.text||fromEmail):String(fromValue||'');
 const subjectRaw=i.json.subject??i.json.threadSubject??pickCI(i.json,'subject')??pickCI(i.json,'threadSubject')??header(hdrs,'subject')??header(p,'subject')??'';
 const subject=String(subjectRaw||'').trim()||'(No subject)';
 const text=i.json.textPlain||i.json.text||i.json.body||bodyFrom(p,'text/plain')||htmlToText(bodyFrom(p,'text/html'))||i.json.snippet||'';
 return { json:{ messageId:i.json.id||i.json.messageId||'', threadId:i.json.threadId||'', fromRaw, fromEmail, subject, text } };
});

const getRaw = (j) =>
  typeof j.text === 'string'
    ? j.text
    : typeof j.response === 'string'
      ? j.response
      : typeof j.output === 'string'
        ? j.output
        : JSON.stringify(j);

const allowed = [
  'job_search',
  'response_needed',
  'skippable',
  'event',
  'application_update',
  'offer_related'
];

return items.map((i) => {
  const raw = getRaw(i.json);
  const s = raw.indexOf('{');
  const e = raw.lastIndexOf('}');

  let p = {};
  if (s >= 0 && e > s) {
    try {
      p = JSON.parse(raw.slice(s, e + 1));
    } catch {}
  }

  const tagList = Array.isArray(p.tags) ? p.tags : [];

  const parsedTags = [
    ...new Set(
      tagList
        .map((t) => String(t || '').trim().toLowerCase())
        .filter((t) => allowed.includes(t))
    )
  ];

  // skippable cannot be combined with any other tag
  const tags = parsedTags.includes('skippable')
    ? parsedTags.length === 1
      ? ['skippable']
      : parsedTags.filter((t) => t !== 'skippable')
    : parsedTags;

  const event = p.event && typeof p.event === 'object'
    ? p.event
    : {};

  const eventTime = String(event.time || '').trim();

  const needs_reply = tags.includes('response_needed');
  const needs_event = tags.includes('event');

  return {
    json: {
      ...i.json,
      tags,
      reason: String(p.reason || ''),
      needs_reply,
      needs_event,
      primary_tag: tags[0] || 'skippable',
      event: {
        title: String(event.title || ''),
        start: eventTime,
        end: '',
        timezone: 'Asia/Hong_Kong',
        location: String(event.location || ''),
        description: String(event.description || '')
      }
    }
  };
});

return items.map(i=>{
  const e=i.json.event||{};
  const title=String(e.title||i.json.subject||'Email event');
  const start=String(e.start||'').trim();
  const timezone=String(e.timezone||'Asia/Hong_Kong');
  const location=String(e.location||'');
  const description=String(e.description||`From: ${i.json.fromRaw||''}\nSubject: ${i.json.subject||''}`);
  let end=String(e.end||'').trim();
  if(!end && start){
    const parsed=new Date(start);
    if(!Number.isNaN(parsed.getTime())) end=new Date(parsed.getTime()+60*60*1000).toISOString();
  }
  return { json:{ ...i.json, calendar:{ title, start, end, timezone, location, description } } };
});

